":"var(--wp--preset--spacing--20)"}}},"css":"html {
 scroll-behavior: smooth;
}

header {
 position: fixed;
 top: 10px;
box-shadow: inset 0px 0px 8px 3px #faebd777;
 z-index: 9999;
background: rgba(255, 255, 255, 0.4);
 backdrop-filter: blur(18px);
-webkit-backdrop-filter: blur(18px);
border-radius: 40px;
left: 50%;
 transform: translateX(-50%);
}


/*Drawer on Mobile & Tablet*/
@media (max-width: 767px) {

#modal-1 {
 position: fixed !important;
 inset: 0 !important;
 width: 100vw;
 height: 100dvh;
 z-index: 999999;
 overflow: visible !important;
}

}

@media (min-width: 1024px) {
 header {
max-width: 1400px;
width: 100%;
 }
}

@media (max-width: 1024px) {
 header {
width: 95%;
 }
}

/*Override overflow hidden in stackable*/
header .stk-7a328bb, header .stk-ac4c16a {
overflow: visible !important;
}
